<?php
$editUser=isset($_GET['edit_user'])?query('SELECT id,username,display_name,role,status FROM users WHERE id=?',[(int)$_GET['edit_user']])->fetch():null;
$users=query('SELECT id,username,display_name,role,status,created_at FROM users ORDER BY id')->fetchAll();
?>
<section class="panel admin-panel"><h2><?=e(t('Users'))?></h2><?php bulkToolbar('users');?><div class="admin-table-wrap"><table class="admin-table selectable-table"><thead><tr><th class="select-cell"><?php selectionBox();?></th><th><?=e(t('Username'))?></th><th><?=e(t('Display name'))?></th><th><?=e(t('Role'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Actions'))?></th></tr></thead><tbody><?php foreach($users as $entry):?><tr><td class="select-cell"><?php selectionBox((int)$entry['id'],$entry['username']);?></td><td><?=e($entry['username'])?></td><td><?=e($entry['display_name'])?></td><td><?=e(t($entry['role']==='admin'?'Administrator':'Member'))?></td><td><?=e(t($entry['status']==='active'?'Active':'Disabled'))?></td><td><a href="/admin/users?edit_user=<?=$entry['id']?>"><?=e(t('Edit'))?></a></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel admin-panel"><h2><?=e(t($editUser?'Edit user':'New user'))?></h2><form class="settings-form" data-admin-action="user_save"><input type="hidden" name="id" value="<?=e($editUser['id']??'')?>"><label><?=e(t('Username'))?><input name="username" pattern="[A-Za-z0-9_][A-Za-z0-9_.-]{2,39}" maxlength="40" value="<?=e($editUser['username']??'')?>" required></label><label><?=e(t('Display name'))?><input name="display_name" maxlength="80" value="<?=e($editUser['display_name']??'')?>"></label><label><?=e(t('Role'))?><select name="role"><option value="user" <?=($editUser['role']??'')==='user'?'selected':''?>><?=e(t('Member'))?></option><option value="admin" <?=($editUser['role']??'')==='admin'?'selected':''?>><?=e(t('Administrator'))?></option></select></label><label><?=e(t('Status'))?><select name="status"><option value="active" <?=($editUser['status']??'')==='active'?'selected':''?>><?=e(t('Active'))?></option><option value="disabled" <?=($editUser['status']??'')==='disabled'?'selected':''?>><?=e(t('Disabled'))?></option></select></label><label><?=e(t('Password'))?><input type="password" name="password" autocomplete="new-password" minlength="10" maxlength="72" <?=$editUser?'':'required'?>></label><p class="muted"><?=e(t('Use 10–72 bytes. Leave blank when editing to keep the current password.'))?></p><button class="button" type="submit"><?=e(t('Save user'))?></button><p role="status"></p></form></section>
